            Pair("papa ka birthday paanch june hai", null),
            Pair("ek do teen char gino", null)
        )
        for ((fact, why) in rows) {
            assertEquals("refuse: $fact", why, PersonalMemory.refuseReason(Logic.norm(fact)))
            val r = PersonalMemory.add(emptyList(), fact)
            if (why == null) assertEquals("saved: $fact", "saved", r.status)
            else {
                assertEquals("refused: $fact", "refused", r.status)
                assertTrue(r.list.isEmpty())
            }
        }
    }

    @Test fun forgetTable() {
        val base = facts.subList(0, 3)
        val rows = listOf(
            Triple("car", 1, false),
            Triple("shiv", 1, false),
            Triple("papa ka naam", 1, false),
            Triple("mera naam", 0, true),
            Triple("kuch nahi", 0, false),
            Triple("", 0, false)
        )
        for ((q, removed, amb) in rows) {
            val r = PersonalMemory.forget(base, q)
            assertEquals("removed for: $q", removed, r.removed)
            assertEquals("ambiguous for: $q", amb, r.ambiguous)
            assertEquals("size after: $q", base.size - removed, r.list.size)
        }
    }

