    @Test fun relevantNeverMoreThanThree() {
        val many = (1..10).map { "tea fact number $it about chai" }
        assertEquals(3, PersonalMemory.relevant(many, "tell me about chai").size)
    }

    @Test fun addDedupesIgnoringCaseAndSpaces() {
        val a = PersonalMemory.add(emptyList(), "mera naam shiv hai")
        assertEquals("saved", a.status)
        val b = PersonalMemory.add(a.list, "MERA   naam shiv HAI")
        assertEquals("dup", b.status)
        assertEquals(1, b.list.size)
    }

    @Test fun addLengthLimits() {
        assertEquals("short", PersonalMemory.add(emptyList(), "ab").status)
        assertEquals("long", PersonalMemory.add(emptyList(), "x".repeat(PersonalMemory.MAX_FACT_CHARS + 1)).status)
        assertEquals("saved", PersonalMemory.add(emptyList(), "y".repeat(PersonalMemory.MAX_FACT_CHARS)).status)
    }

    @Test fun listIsLimitedAndNewestFirst() {
        var l: List<String> = emptyList()
        for (i in 0 until PersonalMemory.MAX_FACTS + 5) l = PersonalMemory.add(l, "fact about tea item$i").list
        assertEquals(PersonalMemory.MAX_FACTS, l.size)
        assertTrue(l[0].endsWith("item" + (PersonalMemory.MAX_FACTS + 4)))
        assertFalse(l.any { it.endsWith("item0") })
    }

